case "${1:-}" in
  --check) check_deps ;;
  --install-deps) install_deps; check_deps ;;
  --uninstall) uninstall ;;
  --help|-h) usage ;;
  "") install ;;
  *) echo "Unknown option: $1" >&2; usage >&2; exit 1 ;;
esac